<?php
use App\Models\Business;use App\Models\Location;use App\Models\Permission;use App\Models\Role;use App\Models\User;use Database\Seeders\PermissionSeeder;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Laravel\Sanctum\Sanctum;
uses(RefreshDatabase::class);beforeEach(fn()=>$this->seed(PermissionSeeder::class));
function oltContext():array{$b=Business::create(['name'=>'Lifecycle','currency'=>'EUR','timezone'=>'Europe/Berlin','status'=>'active']);$l=Location::create(['business_id'=>$b->id,'name'=>'Main','code'=>'MAIN','type'=>'bar','is_active'=>true]);$u=User::create(['name'=>'Manager','email'=>Str::random(10).'@example.test','password'=>bcrypt('password')]);$r=Role::create(['business_id'=>$b->id,'name'=>'Manager','slug'=>'manager-'.Str::random(5),'is_system'=>false]);$r->permissions()->sync(Permission::whereIn('key',['orders.view','orders.create','orders.prepare','orders.cancel'])->pluck('id'));$u->businesses()->attach($b->id,['role_id'=>$r->id,'status'=>'active']);Sanctum::actingAs($u);return[$b,$l,$u,['X-Business-Id'=>$b->id]];}
function oltOrder(Business$b,Location$l,User$u,string$status='open'):array{$oid=(string)Str::ulid();$iid=(string)Str::ulid();$pid=(string)Str::ulid();DB::table('products')->insert(['id'=>$pid,'business_id'=>$b->id,'name'=>'Espresso','sale_price'=>'3.0000','tax_rate'=>'0.0000','is_active'=>true,'tracks_stock'=>false,'created_at'=>now(),'updated_at'=>now()]);DB::table('orders')->insert(['id'=>$oid,'business_id'=>$b->id,'location_id'=>$l->id,'opened_by_user_id'=>$u->id,'number'=>'ORD-'.Str::random(8),'type'=>'takeaway','status'=>$status,'currency'=>'EUR','subtotal'=>'3.0000','discount_total'=>'0.0000','tax_total'=>'0.0000','grand_total'=>'3.0000','opened_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);DB::table('order_items')->insert(['id'=>$iid,'business_id'=>$b->id,'order_id'=>$oid,'product_id'=>$pid,'product_name_snapshot'=>'Espresso','quantity'=>'1.0000','unit_price'=>'3.0000','tax_rate'=>'0.0000','line_subtotal'=>'3.0000','line_tax'=>'0.0000','line_total'=>'3.0000','preparation_station'=>'bar','preparation_status'=>'sent','sent_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);return[$oid,$iid];}
test('preparation lifecycle is strictly forward only and records timestamps',function(){[$b,$l,$u,$h]=oltContext();[,$i]=oltOrder($b,$l,$u);$this->patchJson("/api/v1/order-items/$i/preparation",['status'=>'preparing'],$h)->assertOk()->assertJsonPath('data.preparation_status','preparing');$this->patchJson("/api/v1/order-items/$i/preparation",['status'=>'ready'],$h)->assertOk();$this->patchJson("/api/v1/order-items/$i/preparation",['status'=>'served'],$h)->assertOk();$this->patchJson("/api/v1/order-items/$i/preparation",['status'=>'ready'],$h)->assertStatus(422);expect(DB::table('order_items')->where('id',$i)->value('served_at'))->not->toBeNull();});
test('item cancellation is auditable and recalculates authoritative totals',function(){[$b,$l,$u,$h]=oltContext();[$o,$i]=oltOrder($b,$l,$u);$this->postJson("/api/v1/order-items/$i/cancel",[],$h)->assertStatus(422);$this->postJson("/api/v1/order-items/$i/cancel",['reason'=>'Guest changed order'],$h)->assertOk()->assertJsonPath('data.preparation_status','voided');$row=DB::table('order_items')->where('id',$i)->first();expect($row->void_reason)->toBe('Guest changed order')->and((int)$row->voided_by_user_id)->toBe((int)$u->id)->and(DB::table('orders')->where('id',$o)->value('grand_total'))->toBe('0.0000');});
test('order cancellation voids items and records audit',function(){[$b,$l,$u,$h]=oltContext();[$o,$i]=oltOrder($b,$l,$u);$this->postJson("/api/v1/orders/$o/cancel",['reason'=>'Guest cancelled entire order'],$h)->assertOk()->assertJsonPath('data.status','cancelled');expect(DB::table('orders')->where('id',$o)->value('cancel_reason'))->toBe('Guest cancelled entire order')->and(DB::table('order_items')->where('id',$i)->value('preparation_status'))->toBe('voided');});
test('remaining paid balance blocks cancellation but a full completed refund allows it',function(){[$b,$l,$u,$h]=oltContext();[$o]=oltOrder($b,$l,$u,'payment_due');$pid=(string)Str::ulid();DB::table('payments')->insert(['id'=>$pid,'business_id'=>$b->id,'order_id'=>$o,'collected_by_user_id'=>$u->id,'method'=>'card','status'=>'completed','amount'=>'3.0000','currency'=>'EUR','amount_base'=>'3.0000','base_currency'=>'EUR','exchange_rate'=>'1.0000000000','idempotency_key'=>'p-'.Str::uuid(),'paid_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);$this->postJson("/api/v1/orders/$o/cancel",['reason'=>'Still paid'],$h)->assertStatus(422);DB::table('payment_refunds')->insert(['id'=>(string)Str::ulid(),'business_id'=>$b->id,'payment_id'=>$pid,'refunded_by_user_id'=>$u->id,'amount'=>'3.0000','amount_base'=>'3.0000','currency'=>'EUR','base_currency'=>'EUR','exchange_rate'=>'1.0000000000','reason'=>'Full reversal','idempotency_key'=>'r-'.Str::uuid(),'status'=>'completed','refunded_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);$this->postJson("/api/v1/orders/$o/cancel",['reason'=>'Fully refunded'],$h)->assertOk()->assertJsonPath('data.status','cancelled');});
test('active payment attempt freezes item cancellation',function(){[$b,$l,$u,$h]=oltContext();[$o,$i]=oltOrder($b,$l,$u,'payment_due');DB::table('payments')->insert(['id'=>(string)Str::ulid(),'business_id'=>$b->id,'order_id'=>$o,'collected_by_user_id'=>$u->id,'method'=>'card','status'=>'pending','amount'=>'3.0000','currency'=>'EUR','amount_base'=>'3.0000','base_currency'=>'EUR','exchange_rate'=>'1.0000000000','idempotency_key'=>'p-'.Str::uuid(),'paid_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);$this->postJson("/api/v1/order-items/$i/cancel",['reason'=>'Race attempt'],$h)->assertStatus(422);expect(DB::table('order_items')->where('id',$i)->value('preparation_status'))->toBe('sent');});
test('unresolved payment attempt blocks whole order cancellation',function(){[$b,$l,$u,$h]=oltContext();[$o,$i]=oltOrder($b,$l,$u,'payment_due');DB::table('payments')->insert(['id'=>(string)Str::ulid(),'business_id'=>$b->id,'order_id'=>$o,'collected_by_user_id'=>$u->id,'method'=>'card','status'=>'pending','amount'=>'3.0000','currency'=>'EUR','amount_base'=>'3.0000','base_currency'=>'EUR','exchange_rate'=>'1.0000000000','idempotency_key'=>'p-'.Str::uuid(),'paid_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);$this->postJson(\"/api/v1/orders/$o/cancel\",['reason'=>'Cancel during payment'],$h)->assertStatus(422);expect(DB::table('orders')->where('id',$o)->value('status'))->toBe('payment_due')->and(DB::table('order_items')->where('id',$i)->value('preparation_status'))->toBe('sent');});\ntest('lifecycle endpoints cannot cross tenant boundaries',function(){[$b,$l,$u,$h]=oltContext();$f=Business::create(['name'=>'Foreign','currency'=>'EUR','timezone'=>'UTC','status'=>'active']);$fl=Location::create(['business_id'=>$f->id,'name'=>'Other','code'=>'OTHER','type'=>'bar','is_active'=>true]);$fu=User::create(['name'=>'Foreign','email'=>Str::random(10).'@foreign.test','password'=>bcrypt('password')]);[$o,$i]=oltOrder($f,$fl,$fu);$this->postJson("/api/v1/orders/$o/cancel",['reason'=>'Cross tenant'],$h)->assertNotFound();$this->patchJson("/api/v1/order-items/$i/preparation",['status'=>'preparing'],$h)->assertNotFound();});
